// Build the SOP §3 background-check request email.
// Inbound payload (from Next.js fireOnboardingTemplate):
//   { onboarderId, template:'bg-check-initiate', event, context: {
//     full_name, first_name, personal_email, role_title, onboarding_lead
//   } }

const body = $input.first().json;
const ctx  = body.context || {};
const firstName     = ctx.first_name      || (ctx.full_name || 'there').split(' ')[0];
const toEmail       = ctx.personal_email  || body.to;
const onboardingLead = ctx.onboarding_lead || 'Erich';
const roleTitle     = ctx.role_title      || '';

if (!toEmail) {
  throw new Error('No personal_email on context — cannot send BG-check email');
}

const subject = 'Employment Verification and Reference Check | Romega Solutions';
const body_ = `Hi ${firstName}!

Congratulations on your offer${roleTitle ? ` for the ${roleTitle} role` : ''}! To complete our pre-onboarding process, please send the following information within 48 business hours:

1) PROFESSIONAL CHARACTER REFERENCES (3 required)
Who to provide:
  • Former immediate supervisor (preferred)
  • Work colleague or cross-functional partner
  • For students or recent graduates: professor or instructor

What to include for each referee:
  • Full name
  • Role and company or institution
  • Relationship to you and dates worked or studied together
  • Email address
  • Mobile number and best time to contact

2) EMPLOYMENT VERIFICATION CONTACTS
Please provide the official HR department contact for each previous employer:
  • Company
  • HR contact email
  • HR contact phone
  • Best time to contact

Please ask each referee for permission before sharing their details with Romega. Let them know we may contact them by email or SMS.

Our process:
  1. After we receive your referee list, we will notify them by email and SMS within 24 business hours.
  2. Each referee will have 48 business hours to complete the reference form.
  3. We will keep you updated on progress and any follow-ups needed.

We will contact HR for factual verification and your references for performance feedback separately. If a referee becomes unavailable, kindly send an alternate so we can stay on track.

Cheers,
${onboardingLead}
Onboarding Lead, Romega Solutions`;

return [{ json: { to: toEmail, subject, body: body_, onboarderId: body.onboarderId, template: 'bg-check-initiate' } }];
